CREATE TABLE public.site_content (
  id text PRIMARY KEY DEFAULT 'main',
  data jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.site_content TO anon;
GRANT SELECT, INSERT, UPDATE ON public.site_content TO authenticated;
GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "site content is public" ON public.site_content FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "admins insert site content" ON public.site_content FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(),'admin'::app_role));
CREATE POLICY "admins update site content" ON public.site_content FOR UPDATE TO authenticated USING (has_role(auth.uid(),'admin'::app_role)) WITH CHECK (has_role(auth.uid(),'admin'::app_role));
CREATE TRIGGER site_content_touch BEFORE UPDATE ON public.site_content FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
INSERT INTO public.site_content (id, data) VALUES ('main', '{"brand": "Market Fest", "hero": {"eyebrow": "Oct 2-4, 2026 · Your City, ST", "title": "Market Fest", "lede": "A weekend market built for makers, food lovers, and the whole family.", "image_url": "", "primary_cta": "Become a Vendor", "secondary_cta": "Explore the Festival"}, "badge": {"top": "GOOD VIBES", "middle": "Great Finds", "bottom": "MEMORIES"}, "facts": [{"label": "When", "value": "Oct 2-4, 2026"}, {"label": "Where", "value": "Waterfront Park, Your City"}, {"label": "Admission", "value": "Free & open to the public"}, {"label": "Booth pricing", "value": "from $150"}, {"label": "Vibe", "value": "Family-friendly, all ages"}], "overview": {"eyebrow": "Event Overview", "title": "Three days, built around small business.", "body1": "Market Fest gathers artisans, growers, food trucks and community groups for a three-day celebration on the waterfront. Expect live music, hands-on workshops and a curated mix of booths.", "body2": "Every vendor is hand-picked so shoppers find something new in every aisle, and vendors find customers who actually buy.", "quote": "The best weekend of the year for small makers in our city."}, "expect": [{"eyebrow": "All Weekend", "title": "Live Music", "body": "Local bands on the main stage from noon to dusk each day."}, {"eyebrow": "Family", "title": "Kids Zone", "body": "Free craft tables, face painting and games for all ages."}, {"eyebrow": "Eats", "title": "Food Row", "body": "Food trucks, bakers and coffee roasters lined along the promenade."}], "info": {"note": "Please fill in the application form with your correct information.", "hours": ["Fri Oct 2 — 12:00pm to 8:00pm", "Sat Oct 3 — 10:00am to 8:00pm", "Sun Oct 4 — 10:00am to 5:00pm"], "setup": ["Load-in opens two hours before doors each day", "Vehicles must be clear of the grounds 30 minutes before opening", "Bring your own tent, tables, chairs and weights", "Power is limited — request it on your application"], "overnight": {"title": "Leave your setup overnight", "body": "Vending multiple consecutive days? Leave your booth in place — we provide security overnight for the duration of the event."}}, "pricing": {"eyebrow": "Vendor Pricing", "title": "Simple booth pricing, updated per event.", "subtitle": "Pick the space that fits your setup.", "note": "Prices apply to the full weekend and are confirmed once your application is approved.", "tiers": [{"name": "Standard Booth", "price": "$150", "unit": "per weekend", "featured": false, "features": ["10x10 space", "Listing in the event map", "Overnight security"]}, {"name": "Corner Booth", "price": "$225", "unit": "per weekend", "featured": true, "features": ["10x10 corner space", "Two open sides", "Featured on social media", "Overnight security"]}, {"name": "Food Vendor", "price": "$300", "unit": "per weekend", "featured": false, "features": ["10x20 space", "Power hookup", "Placement on Food Row"]}]}, "policies": [{"title": "Breakdown & General Policies", "items": ["No early breakdown before closing time", "Vendors are responsible for their own waste", "Spaces are non-transferable", "Fees are non-refundable within 14 days of the event"]}, {"title": "Food Vendor Requirements", "items": ["Valid health department permit", "Fire extinguisher on site", "Proof of liability insurance", "Grease containment mats required"]}], "selection": [{"title": "Apply", "body": "Submit the vendor form with photos and product details."}, {"title": "Review", "body": "Our team reviews applications weekly for balance and quality."}, {"title": "Approval", "body": "Approved vendors receive an invoice and booth assignment."}, {"title": "Setup", "body": "Load-in details and your map placement are emailed the week of."}], "vendor_call": {"eyebrow": "Vendor Call", "title": "Vendors Needed!", "body": "Be part of an exciting event that brings together shoppers, food lovers, families, and the community for a weekend of fun, culture, and connection.", "perks": ["Great exposure", "High foot traffic", "Curated vendor mix", "Marketing support"]}, "categories": ["Arts & Crafts", "Food & Beverage", "Home Goods", "Vintage & Thrift", "Wellness", "Plants & Garden", "Community Groups", "Live Demos"], "apply": {"title": "Send us your application", "steps": ["Business name", "Contact information", "Product description", "Photos of products & booth setup", "Website or social media links"], "email": "vendor@example.com", "phone": "(555) 123-4567", "note": "Spaces are limited and carefully curated — early applications are encouraged.", "closing": "Thank you for participating in our events — we look forward to seeing you all!", "form_slug": ""}, "footer": {"blurb": "Arts, Crafts & Food Market Fest — Oct 2-4, 2026.", "address": "Waterfront Park, Your City, ST", "email": "vendor@example.com", "phone": "(555) 123-4567", "socials": [{"label": "Instagram", "url": "https://instagram.com"}, {"label": "Facebook", "url": "https://facebook.com"}], "copyright": "© 2026 Market Fest. All rights reserved."}}'::jsonb);